(function(){var loadHandler=window['sl_{2835D3AF-EACF-4D67-BAF4-03E69812DE9A}'];loadHandler&&loadHandler(22, '<div id="spr0_1773131"><div id="spr1_1773131" class="kern slide"><img id="img1_1773131" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/></div><div id="spr2_1773131" class="kern slide"><div id="spr3_1773131" style="left:127.418px;"><div id="spr4_1773131"><img id="img0_1773131" src="data:image/png;base64," width="960" height="720" alt=""/></div></div><div id="svg4_1773131" style="left:43.238px;top:127.583px;"><svg width="1194" height="465" viewBox="-3 -3 1194 465"><g fill="none"><g transform="translate(1,1)"><path fill="#7f7f7f" fill-opacity="0.55" d="M0,0 H1185.524 V456.833 H0 V0 Z" fill-rule="evenodd"/></g><g transform="translate(1,1)"><path stroke="#042433" stroke-width="2" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="8" d="M0,0 H1185.524 V456.833 H0 V0 Z"/></g></g></svg></div><div id="spr5_1773131" style="left:46.238px;top:130.583px;"><div style="width:0px;"><span id="txt0_1773131" data-width="1165.333252" style="left:10.6px;top:67.584px;">美琉爱的两颗眼球，平静地躺在穣的手心，不同于脑海中拟定的黏稠质感，爱初见时装</span></div><div style="width:0px;"><span id="txt1_1773131" data-width="1165.333252" style="left:10.6px;top:104.384px;">载在眼眶里灵活调动着对焦的那双富有野生气息的瞳眸，糅杂了食肉动物尖锐的利度与</span></div><div style="width:0px;"><span id="txt2_1773131" data-width="1165.333252" style="left:10.6px;top:141.184px;">草食动物沉稳神采的对瞳，化作两枚印了花的玻璃弹珠，让朝仓忆起挤出波子汽水里阻</span></div><div style="width:0px;"><span id="txt3_1773131" data-width="797.333313" style="left:10.6px;top:177.984px;">碍气体喷涌的滚圆，半透明的玉质组织散逸着冰种的寒温。</span></div></div><div id="spr6_1773131" style="left:46.238px;top:130.583px;"><div style="width:0px;"><span id="txt4_1773131" data-width="1165.333252" style="left:10.6px;top:251.584px;">以扁平的门牙为切入点，点画了坑坑洼洼细碎图案的纹理被嵌探，戳穿柔韧纤维外层的</span></div><div style="width:0px;"><span id="txt5_1773131" data-width="1165.333252" style="left:10.6px;top:288.384px;">瞬间仿佛捅破果冻的弹软，甘甜似溏心酒液的房水由舌尖所品味，甜蜜地淌过舌面，顺</span></div><div style="width:0px;"><span id="txt6_1773131" data-width="1165.333252" style="left:10.6px;top:325.184px;">着由味蕾组成的河床汇聚在一点喉间，滋润穣因不安而干涩瘙痒的喉咙，奇迹般使他得</span></div><div style="width:0px;"><span id="txt7_1773131" data-width="214.666656" style="left:10.6px;top:361.984px;">到了一丝安宁。</span></div></div></div></div>', '{"s":[]}');})();